import{_ as o,o as t,c,a3 as n}from"./chunks/framework.BTQ4eCVb.js";const g=JSON.parse('{"title":"Accounting — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Accounting — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/accounting"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Accounting — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/accounting"}]]},"headers":[],"relativePath":"developer-guide/accounting.md","filePath":"developer-guide/accounting.md","lastUpdated":1788108809000}'),d={name:"developer-guide/accounting.md"};function a(r,e,i,s,l,u){return t(),c("div",null,[...e[0]||(e[0]=[n('<h1 id="accounting-—-developer-guide" tabindex="-1">Accounting — Developer Guide <a class="header-anchor" href="#accounting-—-developer-guide" aria-label="Permalink to &quot;Accounting — Developer Guide&quot;">​</a></h1><p>Mirrors the Leads/Expenses module layers under flat <code>app/</code> namespaces. Slug <code>accounting</code>, middleware <code>module:accounting</code>, permissions <code>accounting.*</code>. Catalog version <strong>1.6.0</strong>.</p><h2 id="domain" tabindex="-1">Domain <a class="header-anchor" href="#domain" aria-label="Permalink to &quot;Domain&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Model</th><th>Table</th><th>Notes</th></tr></thead><tbody><tr><td><code>Account</code></td><td><code>accounts</code></td><td>CoA; <code>is_system</code> starter rows; <code>is_cash_bank</code> (asset only); <code>is_header</code> (non-postable); optional parent; list/show include <code>balance</code></td></tr><tr><td><code>JournalEntry</code></td><td><code>journal_entries</code></td><td><code>draft</code> | <code>posted</code> | <code>void</code>; <code>JE-</code> numbers</td></tr><tr><td><code>JournalEntryLine</code></td><td><code>journal_entry_lines</code></td><td>debit XOR credit; FK to postable (non-header) accounts</td></tr><tr><td><code>AccountTransfer</code></td><td><code>account_transfers</code></td><td><code>posted</code> | <code>void</code>; <code>TRF-</code> numbers; linked <code>journal_entry_id</code></td></tr><tr><td><code>AccountBalanceAdjustment</code></td><td><code>account_balance_adjustments</code></td><td><code>posted</code> | <code>void</code>; <code>ADJ-</code> numbers; previous/target/delta + linked JE</td></tr><tr><td><code>AccountingPeriod</code></td><td><code>accounting_periods</code></td><td>fiscal periods; lock/unlock; year-end close</td></tr><tr><td><code>BankReconciliation</code></td><td><code>bank_reconciliations</code></td><td>start against cash/bank; clear lines; complete</td></tr></tbody></table><p>Services: <code>AccountService</code>, <code>JournalEntryService</code>, <code>GeneralLedgerService</code>, <code>ChartOfAccountsSeederService</code>, <code>OpeningBalanceService</code>, <code>CashMovementJournalService</code>, <code>AccountTransferService</code>, <code>AccountBalanceAdjustmentService</code>, <code>AccountingPeriodService</code>, <code>YearEndCloseService</code>.</p><p>Periods: setting <code>fiscal_year_start_month</code> (1–12); journal post/void blocked in locked periods; year-end close zeros P&amp;L into Retained Earnings <code>3100</code> (multi-line JE) and locks the FY period atomically / idempotently. Balance Sheet Net Income uses fiscal YTD (zero after a proper close). Bank rec: start / clear lines / complete against cash/bank accounts — book balance as of statement date, exclude prior cleared lines, require cleared = statement to complete. Invoice send/void and credit-note apply are transactional with period-lock checks.</p><p><code>ChartOfAccountsSeederService</code> seeds starter CoA (incl. Tax Payable <code>2100</code>, Retained Earnings <code>3100</code>) and <code>ensureMissingSystemAccounts</code> backfills missing system codes for existing workspaces.</p><p><code>OpeningBalanceService</code> posts a balanced multi-line opening journal (<code>POST /accounts/opening-balances</code>). Header accounts are rejected on journal lines.</p><p><code>CashMovementJournalService</code> creates+posts two-line journals and voids linked entries. Used by Payments post/void, Expenses pay, Account Transfers, balance adjustments, and invoice/credit accrual hooks.</p><p><code>AccountBalanceAdjustmentService::create</code> reads current balance via <code>FinancialReportService::currentBalancesFor</code>, posts the delta, and stores an <code>ADJ-</code> row (default offset Equity <code>3000</code>).</p><p>Events → <code>AccountingEventSubscriber</code> → <code>PlatformAuditService</code> + Spatie <code>LogsActivity</code>.</p><h2 id="soft-dependents" tabindex="-1">Soft dependents <a class="header-anchor" href="#soft-dependents" aria-label="Permalink to &quot;Soft dependents&quot;">​</a></h2><p>Optional catalog deps (<code>is_optional=true</code>): <strong>invoices → accounting</strong>, <strong>credit-notes → accounting</strong>, <strong>payments → accounting</strong>, <strong>expenses → accounting</strong> (same pattern as payroll → accounting).</p><p>When Accounting is entitled:</p><ul><li>Invoice <strong>send</strong> (<code>CustomerInvoiceService::send</code>): Dr AR <code>1100</code> / Cr Sales Revenue <code>4000</code> (<code>REVENUE_CODE</code>) for invoice total; stores <code>journal_entry_id</code>. <strong>Cancel/void</strong> voids the JE.</li><li>Credit note <strong>apply</strong> (<code>CustomerCreditNoteService::apply</code>): Dr Revenue <code>4000</code> / Cr AR <code>1100</code> for credit total; stores <code>journal_entry_id</code> (applied remains irreversible — no JE void path).</li><li>Payment <strong>post</strong>: allocations must sum to amount; Dr <code>deposit_account_id</code> (or Cash <code>1000</code>) / Cr AR <code>1100</code> (settles receivable booked on send); void voids the JE.</li><li>Expense <strong>pay</strong>: require <code>paid_from_account_id</code>; default expense account <code>6000</code>; Dr expense / Cr paid-from for amount+tax.</li><li>No historical backfill for invoices/credits issued before entitlement.</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><p>See <a href="/api/tenant-v1-accounting">tenant-v1-accounting.md</a>. Payments/expenses account fields: <a href="/api/tenant-v1-payments">tenant-v1-payments</a>, <a href="/api/tenant-v1-expenses">tenant-v1-expenses</a>.</p><h2 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h2><ul><li>Routes: <code>/accounts</code>, <code>/accounts/opening-balances</code>, <code>/journals</code>, <code>/account-transfers</code>, <code>/general-ledger</code></li><li>Accounts: parent picker + <strong>Header</strong> (<code>is_header</code>) on create/edit; headers excluded from journal account pickers</li><li>Journals: classic Account / Debit / Credit / Memo grid (create/edit/view); list Amount column; currency formatting with blank zero Dr/Cr cells</li><li>Account view: <strong>Set balance</strong> dialog + <strong>Balance adjustments</strong> list/void for cash/bank; opening TB via <code>/accounts/opening-balances</code></li><li>General Ledger: currency columns, journal deep links, <strong>Export CSV</strong> (<code>GET /general-ledger/export</code>)</li><li>Nav group <strong>Finance</strong>, dual-gated <code>module: accounting</code> + <code>PERMISSIONS.accounting.view</code></li><li>Production notes: <code>JournalEntryService::post</code> / <code>void</code> use <code>DB::transaction</code> + <code>lockForUpdate()</code>; system account <code>code</code>/<code>type</code> immutable; GL inquiry paginated (100/500); cash movements auto-post (not draft-only like Payroll).</li><li>Playwright (tenant project, one login session per suite): <ul><li>Full module: <code>npm run test:e2e:accounting:modules</code> / <code>:headed</code> — validation, CoA CRUD, journal unbalanced/post/void, transfers smoke, GL</li><li>Authz: <code>npm run test:e2e:accounting:authz</code> / <code>:headed</code> — <code>/403</code>, API 401/403, unbalanced 422</li><li>Smoke + all: <code>npm run test:e2e:accounting</code> / <code>:headed</code></li></ul></li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><p>Pest: <code>tests/Feature/Tenant/Accounting/</code> (CRUD, cash/bank + balances, transfers, balance adjustments, journal post/void, GL), plus <code>CustomerInvoiceAccountingTest</code>, <code>CustomerCreditNoteAccountingTest</code>, <code>CustomerPaymentAccountingTest</code>, <code>ExpenseAccountingTest</code>.</p>',21)])])}const m=o(d,[["render",a]]);export{g as __pageData,m as default};
